package main

import (
	"net/http"
	nethttppprof "net/http/pprof"
	"runtime"
)

func main() {
	// 1) 默认关闭的 profile 必须显式打开，否则拉下来是空文件。
	runtime.SetBlockProfileRate(1)         // 采每一次阻塞事件
	runtime.SetMutexProfileFraction(1)     // 采每一次锁竞争
	// runtime.SetCPUProfileRate(200)      // 默认 100Hz，超过 500Hz 容易丢样本

	// 2) pprof 走独立 admin mux，避免和业务路由共用，方便在网关层只放行内网。
	admin := http.NewServeMux()
	admin.HandleFunc("/debug/pprof/", auth(nethttppprof.Index))
	admin.HandleFunc("/debug/pprof/cmdline", auth(nethttppprof.Cmdline))
	admin.HandleFunc("/debug/pprof/profile", auth(nethttppprof.Profile)) // CPU
	admin.HandleFunc("/debug/pprof/symbol", auth(nethttppprof.Symbol))
	admin.HandleFunc("/debug/pprof/trace", auth(nethttppprof.Trace))     // runtime/trace

	// 3) 仅监听 127.0.0.1，靠 sidecar/跳板机访问；公网暴露等于把堆栈和环境变量送出去。
	go http.ListenAndServe("127.0.0.1:6060", admin)

	http.ListenAndServe(":8080", businessMux())
}

func auth(h http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		u, p, ok := r.BasicAuth()
		if !ok || u != "ops" || p != mustEnv("PPROF_TOKEN") {
			http.Error(w, "forbidden", http.StatusForbidden)
			return
		}
		h(w, r)
	}
}
